import 'package:flutter/material.dart';\nimport 'package:provider/provider.dart';\n\nimport '../../data/repositories/backend_repository.dart';\nimport '../../data/services/router_service_v6.dart';\nimport '../../widgets/loading_state_view.dart';\nimport '../../widgets/section_header.dart';\n\nclass RouterV6ConfigScreen extends StatefulWidget {\n  const RouterV6ConfigScreen({super.key, required this.repository});\n\n  final BackendRepository repository;\n\n  @override\n  State<RouterV6ConfigScreen> createState() => _RouterV6ConfigScreenState();\n}\n\nclass _RouterV6ConfigScreenState extends State<RouterV6ConfigScreen> {\n  final _formKey = GlobalKey<FormState>();\n  final _hostController = TextEditingController(text: '192.168.88.1');\n  final _portController = TextEditingController(text: '8728');\n  final _usernameController = TextEditingController(text: 'admin');\n  final _passwordController = TextEditingController();\n  \n  bool _useSSL = false;\n  bool _forceV6Api = true;\n  bool _isConnecting = false;\n  bool _isConnected = false;\n  String? _connectionError;\n  Map<String, dynamic>? _systemInfo;\n  \n  final RouterService _routerService = RouterService();\n\n  @override\n  void dispose() {\n    _hostController.dispose();\n    _portController.dispose();\n    _usernameController.dispose();\n    _passwordController.dispose();\n    _routerService.disconnect();\n    super.dispose();\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    return Scaffold(\n      appBar: AppBar(\n        title: const Text('إعدادات MikroTik RouterOS v6'),\n        actions: [\n          if (_isConnected)\n            IconButton(\n              onPressed: _testV6Features,\n              icon: const Icon(Icons.speed),\n              tooltip: 'اختبار ميزات v6',\n            ),\n        ],\n      ),\n      body: SingleChildScrollView(\n        padding: const EdgeInsets.all(20),\n        child: Column(\n          crossAxisAlignment: CrossAxisAlignment.start,\n          children: [\n            // معلومات RouterOS v6\n            _buildV6InfoCard(),\n            const SizedBox(height: 20),\n            \n            // إعدادات الاتصال\n            _buildConnectionForm(),\n            const SizedBox(height: 20),\n            \n            // معلومات النظام (إذا كان متصلاً)\n            if (_isConnected && _systemInfo != null)\n              _buildSystemInfoCard(),\n              \n            const SizedBox(height: 20),\n            \n            // اختبارات RouterOS v6\n            if (_isConnected)\n              _buildV6TestsCard(),\n          ],\n        ),\n      ),\n    );\n  }\n\n  Widget _buildV6InfoCard() {\n    return Card(\n      child: Padding(\n        padding: const EdgeInsets.all(16),\n        child: Column(\n          crossAxisAlignment: CrossAxisAlignment.start,\n          children: [\n            const SectionHeader(title: 'معلومات RouterOS v6'),\n            const SizedBox(height: 12),\n            const Text(\n              'RouterOS v6 هو نظام التشغيل المستقر لأجهزة MikroTik مع ميزات User Manager المتقدمة.',\n              style: TextStyle(fontSize: 14),\n            ),\n            const SizedBox(height: 16),\n            \n            // الميزات المدعومة\n            const Text(\n              'الميزات المدعومة:',\n              style: TextStyle(fontWeight: FontWeight.bold),\n            ),\n            const SizedBox(height: 8),\n            _buildFeatureList([\n              'إدارة المستخدمين والعملاء',\n              'نظام البروفايلات المتقدم',\n              'تتبع الجلسات والمدفوعات',\n              'إحصائيات الاستخدام التفصيلية',\n              'API مخصص لـ RouterOS v6',\n              'دعم كامل لـ User Manager',\n            ]),\n            \n            const SizedBox(height: 16),\n            Container(\n              padding: const EdgeInsets.all(12),\n              decoration: BoxDecoration(\n                color: Colors.blue[50],\n                borderRadius: BorderRadius.circular(8),\n                border: Border.all(color: Colors.blue[200]!),\n              ),\n              child: const Row(\n                children: [\n                  Icon(Icons.info, color: Colors.blue),\n                  SizedBox(width: 12),\n                  Expanded(\n                    child: Text(\n                      'تأكد من تفعيل API في IP/Services على المنفذ 8728',\n                      style: TextStyle(color: Colors.blue),\n                    ),\n                  ),\n                ],\n              ),\n            ),\n          ],\n        ),\n      ),\n    );\n  }\n\n  Widget _buildConnectionForm() {\n    return Card(\n      child: Padding(\n        padding: const EdgeInsets.all(16),\n        child: Form(\n          key: _formKey,\n          child: Column(\n            crossAxisAlignment: CrossAxisAlignment.start,\n            children: [\n              const SectionHeader(title: 'إعدادات الاتصال'),\n              const SizedBox(height: 16),\n              \n              // عنوان الراوتر\n              TextFormField(\n                controller: _hostController,\n                decoration: const InputDecoration(\n                  labelText: 'عنوان الراوتر',\n                  hintText: '192.168.88.1',\n                  border: OutlineInputBorder(),\n                ),\n                validator: (value) {\n                  if (value?.isEmpty == true) return 'أدخل عنوان الراوتر';\n                  return null;\n                },\n              ),\n              \n              const SizedBox(height: 16),\n              \n              // المنفذ\n              TextFormField(\n                controller: _portController,\n                keyboardType: TextInputType.number,\n                decoration: const InputDecoration(\n                  labelText: 'المنفذ (API Port)',\n                  hintText: '8728',\n                  border: OutlineInputBorder(),\n                ),\n                validator: (value) {\n                  if (value?.isEmpty == true) return 'أدخل المنفذ';\n                  if (int.tryParse(value!) == null) return 'أدخل رقم صحيح';\n                  return null;\n                },\n              ),\n              \n              const SizedBox(height: 16),\n              \n              // اسم المستخدم\n              TextFormField(\n                controller: _usernameController,\n                decoration: const InputDecoration(\n                  labelText: 'اسم المستخدم',\n                  hintText: 'admin',\n                  border: OutlineInputBorder(),\n                ),\n                validator: (value) {\n                  if (value?.isEmpty == true) return 'أدخل اسم المستخدم';\n                  return null;\n                },\n              ),\n              \n              const SizedBox(height: 16),\n              \n              // كلمة المرور\n              TextFormField(\n                controller: _passwordController,\n                obscureText: true,\n                decoration: const InputDecoration(\n                  labelText: 'كلمة المرور',\n                  border: OutlineInputBorder(),\n                ),\n                validator: (value) {\n                  if (value?.isEmpty == true) return 'أدخل كلمة المرور';\n                  return null;\n                },\n              ),\n              \n              const SizedBox(height: 16),\n              \n              // خيارات إضافية\n              Row(\n                children: [\n                  Expanded(\n                    child: CheckboxListTile(\n                      title: const Text('استخدام SSL'),\n                      subtitle: const Text('المنفذ 8729'),\n                      value: _useSSL,\n                      onChanged: (value) => setState(() => _useSSL = value ?? false),\n                    ),\n                  ),\n                  Expanded(\n                    child: CheckboxListTile(\n                      title: const Text('فرض RouterOS v6'),\n                      subtitle: const Text('API مخصص'),\n                      value: _forceV6Api,\n                      onChanged: (value) => setState(() => _forceV6Api = value ?? true),\n                    ),\n                  ),\n                ],\n              ),\n              \n              const SizedBox(height: 16),\n              \n              // رسالة الخطأ\n              if (_connectionError != null)\n                Container(\n                  padding: const EdgeInsets.all(12),\n                  decoration: BoxDecoration(\n                    color: Colors.red[50],\n                    borderRadius: BorderRadius.circular(8),\n                    border: Border.all(color: Colors.red[200]!),\n                  ),\n                  child: Row(\n                    children: [\n                      const Icon(Icons.error, color: Colors.red),\n                      const SizedBox(width: 12),\n                      Expanded(\n                        child: Text(\n                          _connectionError!,\n                          style: const TextStyle(color: Colors.red),\n                        ),\n                      ),\n                    ],\n                  ),\n                ),\n              \n              const SizedBox(height: 16),\n              \n              // أزرار الاتصال\n              Row(\n                children: [\n                  Expanded(\n                    child: OutlinedButton.icon(\n                      onPressed: _isConnecting || _isConnected ? null : _testConnection,\n                      icon: const Icon(Icons.network_ping),\n                      label: const Text('اختبار الاتصال'),\n                    ),\n                  ),\n                  const SizedBox(width: 16),\n                  Expanded(\n                    child: FilledButton.icon(\n                      onPressed: _isConnecting ? null : (_isConnected ? _disconnect : _connect),\n                      icon: _isConnecting\n                          ? const SizedBox(\n                              width: 16,\n                              height: 16,\n                              child: CircularProgressIndicator(strokeWidth: 2),\n                            )\n                          : Icon(_isConnected ? Icons.link_off : Icons.link),\n                      label: Text(_isConnected ? 'قطع الاتصال' : 'اتصال'),\n                    ),\n                  ),\n                ],\n              ),\n            ],\n          ),\n        ),\n      ),\n    );\n  }\n\n  Widget _buildSystemInfoCard() {\n    return Card(\n      child: Padding(\n        padding: const EdgeInsets.all(16),\n        child: Column(\n          crossAxisAlignment: CrossAxisAlignment.start,\n          children: [\n            const SectionHeader(title: 'معلومات النظام'),\n            const SizedBox(height: 12),\n            \n            ...(_systemInfo!.entries.map((entry) {\n              return Padding(\n                padding: const EdgeInsets.only(bottom: 8),\n                child: Row(\n                  children: [\n                    SizedBox(\n                      width: 120,\n                      child: Text(\n                        '${entry.key}:',\n                        style: const TextStyle(fontWeight: FontWeight.bold),\n                      ),\n                    ),\n                    Expanded(\n                      child: Text(entry.value.toString()),\n                    ),\n                  ],\n                ),\n              );\n            }).toList()),\n          ],\n        ),\n      ),\n    );\n  }\n\n  Widget _buildV6TestsCard() {\n    return Card(\n      child: Padding(\n        padding: const EdgeInsets.all(16),\n        child: Column(\n          crossAxisAlignment: CrossAxisAlignment.start,\n          children: [\n            const SectionHeader(title: 'اختبارات RouterOS v6'),\n            const SizedBox(height: 12),\n            \n            GridView.count(\n              crossAxisCount: 2,\n              shrinkWrap: true,\n              physics: const NeverScrollableScrollPhysics(),\n              childAspectRatio: 3,\n              crossAxisSpacing: 12,\n              mainAxisSpacing: 12,\n              children: [\n                _TestButton(\n                  title: 'اختبار User Manager',\n                  icon: Icons.people,\n                  onTap: () => _testUserManager(),\n                ),\n                _TestButton(\n                  title: 'اختبار البروفايلات',\n                  icon: Icons.account_tree,\n                  onTap: () => _testProfiles(),\n                ),\n                _TestButton(\n                  title: 'اختبار الجلسات',\n                  icon: Icons.timeline,\n                  onTap: () => _testSessions(),\n                ),\n                _TestButton(\n                  title: 'اختبار المدفوعات',\n                  icon: Icons.payment,\n                  onTap: () => _testPayments(),\n                ),\n              ],\n            ),\n          ],\n        ),\n      ),\n    );\n  }\n\n  Widget _buildFeatureList(List<String> features) {\n    return Column(\n      children: features.map((feature) {\n        return Padding(\n          padding: const EdgeInsets.only(bottom: 4),\n          child: Row(\n            children: [\n              const Icon(Icons.check, color: Colors.green, size: 16),\n              const SizedBox(width: 8),\n              Expanded(child: Text(feature, style: const TextStyle(fontSize: 13))),\n            ],\n          ),\n        );\n      }).toList(),\n    );\n  }\n\n  // دوال الاتصال والاختبار\n  Future<void> _testConnection() async {\n    if (!_formKey.currentState!.validate()) return;\n    \n    setState(() {\n      _isConnecting = true;\n      _connectionError = null;\n    });\n\n    try {\n      final host = _hostController.text.trim();\n      final port = int.parse(_portController.text.trim());\n      \n      final success = await RouterService.testConnection(\n        host: host,\n        port: port,\n        timeout: const Duration(seconds: 5),\n      );\n      \n      if (success) {\n        ScaffoldMessenger.of(context).showSnackBar(\n          const SnackBar(\n            content: Text('الاتصال ناجح! ✓'),\n            backgroundColor: Colors.green,\n          ),\n        );\n      } else {\n        setState(() {\n          _connectionError = 'فشل في الاتصال بالراوتر';\n        });\n      }\n    } catch (e) {\n      setState(() {\n        _connectionError = 'خطأ في الاتصال: $e';\n      });\n    } finally {\n      setState(() => _isConnecting = false);\n    }\n  }\n\n  Future<void> _connect() async {\n    if (!_formKey.currentState!.validate()) return;\n    \n    setState(() {\n      _isConnecting = true;\n      _connectionError = null;\n    });\n\n    try {\n      final success = await _routerService.login(\n        host: _hostController.text.trim(),\n        port: int.parse(_portController.text.trim()),\n        username: _usernameController.text.trim(),\n        password: _passwordController.text.trim(),\n        useSSL: _useSSL,\n        forceV6Api: _forceV6Api,\n      );\n      \n      if (success) {\n        setState(() => _isConnected = true);\n        await _loadSystemInfo();\n        \n        ScaffoldMessenger.of(context).showSnackBar(\n          SnackBar(\n            content: Text(\n              'تم الاتصال بنجاح! (${_routerService.connectionInfo})',\n            ),\n            backgroundColor: Colors.green,\n          ),\n        );\n      }\n    } catch (e) {\n      setState(() {\n        _connectionError = e.toString();\n      });\n    } finally {\n      setState(() => _isConnecting = false);\n    }\n  }\n\n  Future<void> _disconnect() async {\n    await _routerService.disconnect();\n    setState(() {\n      _isConnected = false;\n      _systemInfo = null;\n      _connectionError = null;\n    });\n    \n    ScaffoldMessenger.of(context).showSnackBar(\n      const SnackBar(\n        content: Text('تم قطع الاتصال'),\n      ),\n    );\n  }\n\n  Future<void> _loadSystemInfo() async {\n    try {\n      final info = await _routerService.getSystemInfo();\n      setState(() => _systemInfo = info);\n    } catch (e) {\n      // تجاهل الأخطاء\n    }\n  }\n\n  Future<void> _testV6Features() async {\n    showDialog(\n      context: context,\n      builder: (context) => AlertDialog(\n        title: const Text('اختبار ميزات RouterOS v6'),\n        content: const Text(\n          'سيتم اختبار جميع وظائف User Manager المتاحة في RouterOS v6.',\n        ),\n        actions: [\n          TextButton(\n            onPressed: () => Navigator.pop(context),\n            child: const Text('إلغاء'),\n          ),\n          FilledButton(\n            onPressed: () {\n              Navigator.pop(context);\n              _runAllTests();\n            },\n            child: const Text('بدء الاختبار'),\n          ),\n        ],\n      ),\n    );\n  }\n\n  Future<void> _runAllTests() async {\n    final tests = [\n      ('User Manager', _testUserManager),\n      ('البروفايلات', _testProfiles),\n      ('الجلسات', _testSessions),\n      ('المدفوعات', _testPayments),\n    ];\n\n    for (final (name, test) in tests) {\n      try {\n        await test();\n        ScaffoldMessenger.of(context).showSnackBar(\n          SnackBar(\n            content: Text('✓ اختبار $name نجح'),\n            backgroundColor: Colors.green,\n            duration: const Duration(seconds: 1),\n          ),\n        );\n      } catch (e) {\n        ScaffoldMessenger.of(context).showSnackBar(\n          SnackBar(\n            content: Text('✗ اختبار $name فشل: $e'),\n            backgroundColor: Colors.red,\n            duration: const Duration(seconds: 2),\n          ),\n        );\n      }\n      \n      await Future.delayed(const Duration(milliseconds: 500));\n    }\n  }\n\n  Future<void> _testUserManager() async {\n    await _routerService.getAllUsers();\n  }\n\n  Future<void> _testProfiles() async {\n    await _routerService.getProfiles();\n  }\n\n  Future<void> _testSessions() async {\n    await _routerService.getActiveSessions();\n  }\n\n  Future<void> _testPayments() async {\n    await _routerService.runCustomCommand(['/tool/user-manager/payment/print']);\n  }\n}\n\nclass _TestButton extends StatelessWidget {\n  const _TestButton({\n    required this.title,\n    required this.icon,\n    required this.onTap,\n  });\n\n  final String title;\n  final IconData icon;\n  final VoidCallback onTap;\n\n  @override\n  Widget build(BuildContext context) {\n    return Card(\n      child: InkWell(\n        onTap: onTap,\n        borderRadius: BorderRadius.circular(8),\n        child: Padding(\n          padding: const EdgeInsets.all(12),\n          child: Row(\n            children: [\n              Icon(icon, color: Theme.of(context).colorScheme.primary),\n              const SizedBox(width: 12),\n              Expanded(\n                child: Text(\n                  title,\n                  style: const TextStyle(fontSize: 14, fontWeight: FontWeight.w500),\n                ),\n              ),\n            ],\n          ),\n        ),\n      ),\n    );\n  }\n}"